export class CliError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const tasks = new Map() // name -> cost
  const taskLine = new Map() // name -> line declared (for diagnostics if ever needed)
  const deps = new Map() // name -> array of unique dependency names, in first-seen order
  const usedNames = [] // order of first appearance of any name used on a dep line
  const usedSeen = new Set()

  function noteUsed(name) {
    if (!usedSeen.has(name)) {
      usedSeen.add(name)
      usedNames.push(name)
    }
  }

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`error: line ${lineNo}: expected task <name> <cost>`, 2)
      }
      const name = words[1]
      const costStr = words[2]
      if (!NAME_RE.test(name)) {
        throw new CliError(`error: line ${lineNo}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`error: line ${lineNo}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`error: line ${lineNo}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, parseInt(costStr, 10))
      taskLine.set(name, lineNo)
      if (!deps.has(name)) deps.set(name, [])
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`error: line ${lineNo}: expected dep <name> <dependency>...`, 2)
      }
      for (const name of words.slice(1)) {
        if (!NAME_RE.test(name)) {
          throw new CliError(`error: line ${lineNo}: invalid task name ${name}`, 2)
        }
      }
      const name = words[1]
      noteUsed(name)
      if (!deps.has(name)) deps.set(name, [])
      const list = deps.get(name)
      for (const dep of words.slice(2)) {
        noteUsed(dep)
        if (!list.includes(dep)) list.push(dep)
      }
    } else {
      throw new CliError(`error: line ${lineNo}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of usedNames) {
    if (!tasks.has(name)) {
      throw new CliError(`error: unknown task ${name}`, 2)
    }
  }

  return { tasks, deps }
}
"}

