{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-PPFFfz/src/schedule.js","content":"/**
 * Graph analysis: cycle detection, wave/depth/start/finish computation, and
 * the multi-worker packing simulation.
 */

import { CliError } from './parse.js'

/**
 * Finds a cycle, if any, via depth-first search starting from each task in
 * ascending name order and walking dependencies in ascending name order.
 * Throws a CliError with the cycle message when one is found.
 */
export function checkCycles(tasks, deps) {
  const names = Array.from(tasks.keys()).sort()
  const visited = new Set()
  const onStack = new Set()
  const stack = []

  function visit(name) {
    stack.push(name)
    onStack.add(name)
    const ds = Array.from(deps.get(name) || []).sort()
    for (const dep of ds) {
      if (onStack.has(dep)) {
        const idx = stack.indexOf(dep)
        const cycle = stack.slice(idx).concat(dep)
        throw new CliError(`error: cycle: ${cycle.join(' -> ')}`, 3)
      }
      if (!visited.has(dep)) {
        visit(dep)
      }
    }
    stack.pop()
    onStack.delete(name)
    visited.add(name)
  }

  for (const name of names) {
    if (!visited.has(name)) visit(name)
  }
}

/**
 * Computes depth (wave), start and finish for every task. Assumes the graph
 * has already been checked for cycles.
 */
export function computeTimes(tasks, deps) {
  const depth = new Map()
  const start = new Map()
  const finish = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const ds = deps.get(name) || []
    if (ds.length === 0) {
      depth.set(name, 0)
      start.set(name, 0)
    } else {
      let maxDepth = -1
      let maxFinish = 0
      for (const dep of ds) {
        compute(dep)
        if (depth.get(dep) > maxDepth) maxDepth = depth.get(dep)
        if (finish.get(dep) > maxFinish) maxFinish = finish.get(dep)
      }
      depth.set(name, maxDepth + 1)
      start.set(name, maxFinish)
    }
    finish.set(name, start.get(name) + tasks.get(name))
  }

  for (const name of tasks.keys()) compute(name)

  return { depth, start, finish }
}

/**
 * Groups tasks into waves by their depth, sorted ascending inside each wave.
 */
export function computeWaves(tasks, depth) {
  const waves = []
  for (const name of tasks.keys()) {
    const d = depth.get(name)
    if (!waves[d]) waves[d] = []
    waves[d].push(name)
  }
  for (const wave of waves) {
    if (wave) wave.sort()
  }
  return waves
}

/**
 * Computes each task's priority: the cost of the longest chain that begins
 * at it and runs down through its dependents to a task nothing depends on.
 */
export function computePriorities(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, ds] of deps.entries()) {
    for (const dep of ds) {
      if (!dependents.has(dep)) dependents.set(dep, [])
      dependents.get(dep).push(name)
    }
  }

  const priority = new Map()
  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const child of dependents.get(name) || []) {
      const p = compute(child)
      if (p > best) best = p
    }
    const result = tasks.get(name) + best
    priority.set(name, result)
    return result
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

/**
 * Simulates the graph on the given number of workers, returning the
 * per-worker task log and the overall makespan.
 */
export function pack(tasks, deps, workerCount) {
  const priority = computePriorities(tasks, deps)
  const names = Array.from(tasks.keys())
  const total = names.length

  const workerFreeAt = new Array(workerCount).fill(0)
  const workerLog = Array.from({ length: workerCount }, () => [])
  const finishOf = new Map()
  const started = new Set()

  let t = 0
  while (started.size < total) {
    let progressed = true
    while (progressed) {
      progressed = false
      const freeWorkers = []
      for (let i = 0; i < workerCount; i++) {
        if (workerFreeAt[i] <= t) freeWorkers.push(i)
      }
      if (freeWorkers.length === 0) break

      const ready = []
      for (const name of names) {
        if (started.has(name)) continue
        const ds = deps.get(name) || []
        let ok = true
        for (const dep of ds) {
          const f = finishOf.get(dep)
          if (f === undefined || f > t) {
            ok = false
            break
          }
        }
        if (ok) ready.push(name)
      }
      if (ready.length === 0) break

      ready.sort((a, b) => {
        const pa = priority.get(a)
        const pb = priority.get(b)
        if (pa !== pb) return pb - pa
        return a < b ? -1 : a > b ? 1 : 0
      })
      const chosen = ready[0]
      const workerIndex = freeWorkers[0]
      const s = t
      const f = t + tasks.get(chosen)
      workerLog[workerIndex].push({ name: chosen, start: s, finish: f })
      workerFreeAt[workerIndex] = f
      finishOf.set(chosen, f)
      started.add(chosen)
      progressed = true
    }

    if (started.size >= total) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerFreeAt[i] > t && workerFreeAt[i] < next) next = workerFreeAt[i]
    }
    if (!Number.isFinite(next)) break
    t = next
  }

  let makespan = 0
  for (const f of finishOf.values()) {
    if (f > makespan) makespan = f
  }

  return { workerLog, makespan }
}
"}

