import { CliError, parseGraph } from './parse.js'
import { checkCycles, computeTimes, computeWaves, pack } from './schedule.js'

function readStdin() {
  const fs = require('node:fs')
  try {
    return fs.readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

