  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  usageError()
}

async function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)

  const input = await readStdinAsync()
  const { tasks, deps } = parseGraph(input)
  checkCycles(tasks, deps)

  if (args.mode === 'waves') {
    const { depth, finish } = computeTimes(tasks, deps)
    const waves = computeWaves(tasks, depth)
    let out = ''
    for (let i = 0; i < waves.length; i++) {
      const wave = waves[i] || []
      out += `wave ${i}: ${wave.join(' ')}\n`
    }
    let total = 0
    for (const f of finish.values()) {
      if (f > total) total = f
    }
    out += `total ${total}\n`
    process.stdout.write(out)
  } else if (args.mode === 'explain') {
    const { depth, start, finish } = computeTimes(tasks, deps)
    const names = Array.from(tasks.keys()).sort()
    let out = ''
    for (const name of names) {
      out += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
    }
    let total = 0
    for (const f of finish.values()) {
      if (f > total) total = f
    }
    out += `total ${total}\n`
    process.stdout.write(out)
  } else if (args.mode === 'pack') {
    const { workerLog, makespan } = pack(tasks, deps, args.workers)
    let out = ''
    for (let i = 0; i < workerLog.length; i++) {
      const entries = workerLog[i].map((e) => ` ${e.name}@${e.start}-${e.finish}`).join('')
      out += `worker ${i}:${entries}\n`
    }
    out += `makespan ${makespan}\n`
    process.stdout.write(out)
  }
}

